mapper.select:
SELECT TRUNC(statistics_time) AS date, COALESCE(ROUND(AVG(utilization_rate),2),0) AS useRate FROM bbx_meeting_room_daily_statistics WHERE statistics_time >= TRUNC(SYSDATE) - 30
AND tenant_id = #{tenantId}
GROUP BY TRUNC(statistics_time) ORDER BY date

SELECT room_id AS id, COALESCE(ROUND(AVG(utilization_rate),2),0) AS avgRate FROM bbx_meeting_room_daily_statistics WHERE statistics_time >= TRUNC(SYSDATE) - 30
AND tenant_id = #{tenantId}
GROUP BY room_id ORDER BY avgRate DESC
